//! Embedded columns of engine tables: the DDL.
//!
//! ```text
//! c VECTOR(n) GENERATED BY EMBEDDING(src) USING MODEL 'm' ... on an engine table
//!   the table's columns: c VARBINARY(4n) NULL (the vector, n little-endian
//!   f32s, as VECTOR(n) stores it), _sprig_emb_c_src (the source, VIRTUAL,
//!   INVISIBLE, its comment the clause's settings) and _sprig_emb_c_hash
//!   BINARY(16) INVISIBLE (MD5 of the source the vector was made from)
//!   run through the session (its privileges apply), hidden names allowed
//!   then an EngineColumn record (backfilling, changes from now on) in the
//!   tenant's catalog records; this gateway's runner fills c
//!   (embed_ddl::runner) on the node that leads the tenant's unit
//! ALTER TABLE t DROP [COLUMN] c: the hidden columns go too, then the record
//! ALTER TABLE t MODIFY [COLUMN] c ... GENERATED BY EMBEDDING: 39997 (a new
//!   generation isn't built on engine tables; drop the column and add it)
//! ALTER TABLE t CHANGE | MODIFY | RENAME COLUMN | ALTER COLUMN c: 39997
//! ```
//!
//! The source is checked by the engine as any generated column's (the
//! row's own columns; the clause itself refuses non-deterministic
//! functions, variables and subqueries).

use std::time::{SystemTime, UNIX_EPOCH};

use sprig_ai::embedding::failed;
use sprig_ai::embedding::store::{EngineColumn, EngineColumns, State};
use sprig_catalog::TenantCatalog;
use sprig_common::ids::ObjectId;
use sprig_common::{Result, SprigError};
use sprig_sql::embedcol::{self, Clause, Meta, Touch, quote};

use super::super::PassSession;
use crate::engine::table::{Family, TableDef};
use crate::pipeline::{ExecCtx, Wire};

/// A string literal (no backslash escapes assumed in the comment text).
fn lit(s: &str) -> String {
    format!("'{}'", s.replace('\\', "\\\\").replace('\'', "''"))
}

/// The engine's column definitions of a clause: the vector as
/// `VARBINARY(4n)`, the hidden source and the hidden hash.
#[must_use]
pub(crate) fn column_defs(c: &Clause) -> Vec<String> {
    let meta = Meta {
        column: c.column.clone(),
        model: c.model.clone(),
        generation: 1,
        mode: c.mode,
        max_input_tokens: c.max_input_tokens,
        shadow: false,
    };
    vec![
        format!(
            "{} VARBINARY({}) NULL DEFAULT NULL",
            quote(&c.column),
            c.dim.saturating_mul(4)
        ),
        format!(
            "{} MEDIUMTEXT GENERATED ALWAYS AS ({}) VIRTUAL INVISIBLE COMMENT {}",
            quote(&embedcol::src_column(&c.column, None)),
            c.source,
            lit(&meta.comment())
        ),
        format!(
            "{} BINARY(16) NULL DEFAULT NULL INVISIBLE",
            quote(&embedcol::hash_column(&c.column, None))
        ),
    ]
}

/// Whether `db` is an engine database of `cat`.
pub(crate) fn is_engine_db(cat: &TenantCatalog, db: &str, lctn: bool) -> bool {
    let Some(d) = cat.database(&sprig_catalog::ddl::database_key(db, lctn)) else {
        return false;
    };
    crate::engine::catalog::of(cat).is_some_and(|e| e.dbs.contains(&d.db_id))
}

/// The engine's definition of `db`.`table`.
pub(crate) fn table_def(
    cat: &TenantCatalog,
    db: &str,
    table: &str,
    lctn: bool,
) -> Option<std::sync::Arc<TableDef>> {
    let d = cat.database(&sprig_catalog::ddl::database_key(db, lctn))?;
    crate::engine::catalog::of(cat)?
        .table(d.db_id, table, lctn)?
        .as_ref()
        .as_ref()
        .ok()
        .cloned()
}

/// Whether `db` has a table or view named `name` now.
pub(crate) fn relation_exists(cat: &TenantCatalog, db: &str, name: &str, lctn: bool) -> bool {
    if table_def(cat, db, name, lctn).is_some() {
        return true;
    }
    let Some(d) = cat.database(&sprig_catalog::ddl::database_key(db, lctn)) else {
        return false;
    };
    crate::engine::catalog::of(cat).is_some_and(|e| e.view(d.db_id, name, lctn).is_some())
}

/// The engine's definition of table `object`.
pub(crate) fn table_by_object(
    cat: &TenantCatalog,
    object: u64,
) -> Option<std::sync::Arc<TableDef>> {
    crate::engine::catalog::of(cat)?
        .tables
        .get(&ObjectId(object))?
        .as_ref()
        .as_ref()
        .ok()
        .cloned()
}

/// Whether row-level security limits `user` on table `object`: the
/// column fills every row, so its declarer must see them all (bypass row
/// security, be exempt from the table's policies, or the table has none).
pub(crate) fn bound_by_rls(cat: &TenantCatalog, user: u32, object: u64) -> bool {
    let Some(state) = sprig_auth::authz::AuthzState::of(cat) else {
        return false;
    };
    let u = sprig_common::ids::UserId(user);
    let c = sprig_auth::authz::CompiledPrivileges::compile(state, u, &state.default_roles(u));
    sprig_auth::authz::rls::compile(cat, &c, u)
        .tables
        .contains_key(&ObjectId(object))
}

/// 39997 for a declarer that row-level security limits on the table.
pub(crate) fn rls_refused(table: &str) -> SprigError {
    failed(format!(
        "{table}: row-level security limits you on this table, and an embedded column fills every row; it needs a user that bypasses row-level security (BYPASS RLS) or that the table's policies don't limit"
    ))
}

/// Refuses a table whose key the runner can't use.
fn check_key(def: &TableDef) -> Result<()> {
    if def.hidden || def.pk.is_empty() {
        return Err(failed(format!(
            "{}: a table with embedded columns needs a primary key",
            def.name
        )));
    }
    for &i in &def.pk {
        let Some(c) = def.columns.get(i) else {
            continue;
        };
        if matches!(Family::of(c.ty), Family::Float | Family::Json | Family::Bit) {
            return Err(failed(format!(
                "{}: an embedded column's table needs a primary key of numbers, text, dates or binary strings ({} isn't)",
                def.name, c.name
            )));
        }
    }
    Ok(())
}

fn now_ms() -> i64 {
    i64::try_from(
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_or(0, |d| d.as_millis()),
    )
    .unwrap_or(i64::MAX)
}

impl PassSession {
    /// The lower-case-names flag and a fresh catalog.
    pub(super) async fn embed_cat(&mut self) -> Result<(std::sync::Arc<TenantCatalog>, bool)> {
        let ts = self
            .tenant
            .as_deref_mut()
            .ok_or_else(|| SprigError::internal("no tenant"))?;
        let lctn = ts.lower_case_table_names();
        let cat = ts.refresh().await?;
        Ok((cat, lctn))
    }

    /// `CREATE TABLE` or `ALTER TABLE ... ADD` with embedding clauses on
    /// an engine table.
    #[allow(clippy::too_many_arguments, clippy::too_many_lines)] // the statement and its parts
    pub(super) async fn engine_declare(
        &mut self,
        cx: &mut ExecCtx<'_>,
        wire: Wire,
        sql: &str,
        db: &str,
        table: &str,
        create: bool,
        clauses: &[Clause],
    ) -> Result<()> {
        let (svc, tenant, user) = self.services_and_tenant()?;
        let (cat, lctn) = self.embed_cat().await?;
        let mut models = Vec::with_capacity(clauses.len());
        for c in clauses {
            models.push(Self::model_for(&svc, &cat, c)?);
        }
        // A table already there: the statement runs as the servers run it
        // (`IF NOT EXISTS`: nothing happens; without it: 1050), and nothing
        // here touches the table or its records afterwards.
        let existed = create && relation_exists(&cat, db, table, lctn);
        if create {
            if !sql.to_ascii_uppercase().contains("PRIMARY KEY") {
                return Err(failed(format!(
                    "{table}: a table with embedded columns needs a primary key"
                )));
            }
        } else if let Some(def) = table_def(&cat, db, table, lctn) {
            check_key(&def)?;
            if bound_by_rls(&cat, user, def.object.0) {
                return Err(rls_refused(table));
            }
        }
        let edits: Vec<(std::ops::Range<usize>, String)> = clauses
            .iter()
            .map(|c| {
                let defs = column_defs(c);
                let text = if create {
                    defs.join(", ")
                } else {
                    defs.iter()
                        .map(|d| format!("ADD COLUMN {d}"))
                        .collect::<Vec<_>>()
                        .join(", ")
                };
                (c.span.clone(), text)
            })
            .collect();
        let rewritten = embedcol::splice(sql, edits);
        self.embed_run(cx, wire, &rewritten).await?;
        if existed {
            return Ok(());
        }
        let (cat, lctn) = self.embed_cat().await?;
        let Some(def) = table_def(&cat, db, table, lctn) else {
            return Err(SprigError::internal(format!(
                "{db}.{table} isn't in the catalog after its DDL"
            )));
        };
        if let Err(e) = check_key(&def) {
            // A table this statement made whose key won't do: it goes again.
            if create {
                let _ = self
                    .embed_run(
                        cx,
                        wire,
                        &format!("DROP TABLE {}.{}", quote(db), quote(table)),
                    )
                    .await;
            }
            return Err(e);
        }
        let rows: Vec<EngineColumn> = clauses
            .iter()
            .zip(models)
            .map(|(c, m)| EngineColumn {
                id: 0,
                db_id: def.db.0,
                object_id: def.object.0,
                column: c.column.clone(),
                source: c.source.clone(),
                model: m,
                alias: c.model.clone(),
                max_input_tokens: c.max_input_tokens,
                state: State::Backfilling,
                from_ms: now_ms(),
                token: None,
                backfilled: false,
                backfill_after: None,
                rows_embedded: 0,
                rows_failed: 0,
                last_error: None,
                created_by: user,
            })
            .collect();
        match self.insert_columns(&rows).await {
            Ok(ids) => {
                for (id, r) in ids.iter().zip(&rows) {
                    tracing::info!(%tenant, %db, %table, column = %r.column, embedding = id, "embedded column declared on an engine table");
                }
            }
            Err(e) => {
                // No column without its record: the DDL is undone.
                let undo = if create {
                    format!("DROP TABLE {}.{}", quote(db), quote(table))
                } else {
                    let drops: Vec<String> = clauses
                        .iter()
                        .flat_map(|c| {
                            [
                                c.column.clone(),
                                embedcol::src_column(&c.column, None),
                                embedcol::hash_column(&c.column, None),
                            ]
                        })
                        .map(|n| format!("DROP COLUMN {}", quote(&n)))
                        .collect();
                    format!(
                        "ALTER TABLE {}.{} {}",
                        quote(db),
                        quote(table),
                        drops.join(", ")
                    )
                };
                if let Err(u) = self.embed_run(cx, wire, &undo).await {
                    tracing::warn!(%tenant, %db, %table, error = %u, "an embedded column's DDL couldn't be undone after its record failed");
                }
                return Err(e);
            }
        }
        super::runner::wake();
        Ok(())
    }

    /// Adds `rows` to the tenant's embedded-column records in one
    /// transaction; their new ids.
    async fn insert_columns(&self, rows: &[EngineColumn]) -> Result<Vec<u64>> {
        let (svc, tenant, _) = self.services_and_tenant()?;
        let mut tx = super::super::ai_fn::writers(&svc).begin(tenant).await?;
        let mut ids = Vec::with_capacity(rows.len());
        for r in rows {
            ids.push(EngineColumns.insert(&mut *tx, r).await?);
        }
        tx.commit().await?;
        Ok(ids)
    }

    /// The embedded columns of engine table `object`.
    pub(super) async fn engine_embedded_of(&self, object: u64) -> Result<Vec<EngineColumn>> {
        let (svc, tenant, _) = self.services_and_tenant()?;
        let mut tx = super::super::ai_fn::writers(&svc).begin(tenant).await?;
        let r = EngineColumns.of_object(&mut *tx, object).await;
        tx.rollback().await?;
        r
    }

    /// An `ALTER TABLE` touching columns of an engine table: `false` when
    /// none is embedded.
    pub(super) async fn engine_touches(
        &mut self,
        cx: &mut ExecCtx<'_>,
        wire: Wire,
        sql: &str,
        def: &TableDef,
        specs: &[(Touch, String, std::ops::Range<usize>)],
    ) -> Result<bool> {
        let embedded = self.engine_embedded_of(def.object.0).await?;
        let has = |n: &str| def.columns.iter().any(|c| c.name.eq_ignore_ascii_case(n));
        // Every record of the column (older builds could leave two).
        let find = |c: &str| -> Vec<&EngineColumn> {
            embedded
                .iter()
                .filter(|e| e.column.eq_ignore_ascii_case(c))
                .collect()
        };
        let mut edits = Vec::new();
        let mut dropped = Vec::new();
        let mut any = false;
        for (kind, column, span) in specs {
            // An embedded column: its record, or its hidden siblings (a
            // copy made by `CREATE TABLE ... LIKE` before its record, or a
            // record lost).
            let siblings: Vec<String> = [
                embedcol::src_column(column, None),
                embedcol::hash_column(column, None),
            ]
            .into_iter()
            .filter(|n| has(n))
            .collect();
            let rec = find(column);
            if rec.is_empty() && siblings.is_empty() {
                continue;
            }
            if *kind != Touch::Drop {
                return Err(failed(format!(
                    "{column} is an embedded column: it can't be changed, renamed or retyped; \
                     drop it and add it again"
                )));
            }
            let extra: Vec<String> = siblings
                .iter()
                .map(|n| format!("DROP COLUMN {}", quote(n)))
                .collect();
            let text = if extra.is_empty() {
                sql[span.clone()].to_owned()
            } else {
                format!("{}, {}", &sql[span.clone()], extra.join(", "))
            };
            edits.push((span.clone(), text));
            dropped.extend(rec.into_iter().cloned());
            any = true;
        }
        if !any {
            return Ok(false);
        }
        let rewritten = embedcol::splice(sql, edits);
        self.embed_run(cx, wire, &rewritten).await?;
        let (svc, tenant, _) = self.services_and_tenant()?;
        let mut tx = super::super::ai_fn::writers(&svc).begin(tenant).await?;
        for e in &dropped {
            EngineColumns.delete(&mut *tx, e.id).await?;
        }
        tx.commit().await?;
        for e in dropped {
            tracing::info!(%tenant, table = %def.name, column = %e.column, embedding = e.id, "embedded column dropped");
        }
        Ok(true)
    }
}

/// `CREATE [TEMPORARY] TABLE [IF NOT EXISTS] [db.]b LIKE [db.]a`, or with
/// `(LIKE ...)`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct LikeStmt {
    pub temporary: bool,
    pub db: Option<String>,
    pub table: String,
    pub src_db: Option<String>,
    pub src: String,
}

/// The words, `` `quoted` `` names, dots and parentheses of `sql`; `None`
/// for anything else (a comment, a string, a semicolon).
fn like_tokens(sql: &str) -> Option<Vec<(bool, String)>> {
    let b = sql.trim().trim_end_matches(';').as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c.is_ascii_whitespace() {
            i += 1;
        } else if c == b'`' {
            let mut name = Vec::new();
            i += 1;
            loop {
                match (b.get(i), b.get(i + 1)) {
                    (Some(b'`'), Some(b'`')) => {
                        name.push(b'`');
                        i += 2;
                    }
                    (Some(b'`'), _) => {
                        i += 1;
                        break;
                    }
                    (Some(x), _) => {
                        name.push(*x);
                        i += 1;
                    }
                    (None, _) => return None,
                }
            }
            out.push((true, String::from_utf8(name).ok()?));
        } else if matches!(c, b'.' | b'(' | b')') {
            out.push((false, (c as char).to_string()));
            i += 1;
        } else if c.is_ascii_alphanumeric() || c == b'_' || c == b'$' {
            let st = i;
            while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'_' || b[i] == b'$') {
                i += 1;
            }
            out.push((false, String::from_utf8(b[st..i].to_vec()).ok()?));
        } else {
            return None;
        }
    }
    Some(out)
}

/// [`LikeStmt`] of `sql`, when it is one.
#[allow(clippy::many_single_char_names)] // tokens and positions
pub(crate) fn parse_like(sql: &str) -> Option<LikeStmt> {
    let t = like_tokens(sql)?;
    let word = |i: usize, w: &str| {
        t.get(i)
            .is_some_and(|(q, x)| !q && x.eq_ignore_ascii_case(w))
    };
    let mut i = 0;
    if !word(i, "CREATE") {
        return None;
    }
    i += 1;
    let temporary = word(i, "TEMPORARY");
    if temporary {
        i += 1;
    }
    if !word(i, "TABLE") {
        return None;
    }
    i += 1;
    if word(i, "IF") && word(i + 1, "NOT") && word(i + 2, "EXISTS") {
        i += 3;
    }
    let name = |i: &mut usize| -> Option<(Option<String>, String)> {
        let (q, a) = t.get(*i)?.clone();
        if !q && matches!(a.as_str(), "." | "(" | ")") {
            return None;
        }
        *i += 1;
        if t.get(*i).is_some_and(|(q, x)| !q && x == ".") {
            let (q2, b) = t.get(*i + 1)?.clone();
            if !q2 && matches!(b.as_str(), "." | "(" | ")") {
                return None;
            }
            *i += 2;
            return Some((Some(a), b));
        }
        Some((None, a))
    };
    let (db, table) = name(&mut i)?;
    let paren = t.get(i).is_some_and(|(q, x)| !q && x == "(");
    if paren {
        i += 1;
    }
    if !word(i, "LIKE") {
        return None;
    }
    i += 1;
    let (src_db, src) = name(&mut i)?;
    if paren {
        if !t.get(i).is_some_and(|(q, x)| !q && x == ")") {
            return None;
        }
        i += 1;
    }
    (i == t.len()).then_some(LikeStmt {
        temporary,
        db,
        table,
        src_db,
        src,
    })
}

impl PassSession {
    /// `CREATE TABLE b LIKE a` where `a` is an engine table with embedded
    /// columns: the copy (hidden columns and all) is made as usual, then
    /// gets the hidden columns it lacks and records of its own, so its rows
    /// are filled too. `false` for
    /// any other `LIKE` (it runs as usual).
    #[allow(clippy::too_many_lines)] // the copy, its hidden columns, its records
    pub(super) async fn engine_like(
        &mut self,
        cx: &mut ExecCtx<'_>,
        wire: Wire,
        text: &[u8],
        like: &LikeStmt,
    ) -> Result<bool> {
        let current = self.current_logical();
        let Some(src_db) = like.src_db.clone().or_else(|| current.clone()) else {
            return Ok(false);
        };
        let Some(db) = like.db.clone().or(current) else {
            return Ok(false);
        };
        let (cat, lctn) = self.embed_cat().await?;
        if !is_engine_db(&cat, &src_db, lctn) {
            return Ok(false);
        }
        let Some(src) = table_def(&cat, &src_db, &like.src, lctn) else {
            return Ok(false);
        };
        let from = self.engine_embedded_of(src.object.0).await?;
        if from.is_empty() {
            return Ok(false);
        }
        if like.temporary {
            return Err(failed(format!(
                "{}: a temporary copy of a table with embedded columns isn't available",
                like.src
            )));
        }
        let (_, _, user) = self.services_and_tenant()?;
        // A table already there: the statement runs as the servers run it
        // (`IF NOT EXISTS`: nothing happens; without it: 1050), and the
        // table and its records are left as they are.
        let existed = relation_exists(&cat, &db, &like.table, lctn);
        self.embed_run(cx, wire, &String::from_utf8_lossy(text))
            .await?;
        if existed {
            return Ok(true);
        }
        let (cat, lctn) = self.embed_cat().await?;
        let Some(def) = table_def(&cat, &db, &like.table, lctn) else {
            return Err(SprigError::internal(format!(
                "{db}.{} isn't in the catalog after its DDL",
                like.table
            )));
        };
        // The copy's hidden columns, added when the copy left them out.
        let has = |n: &str| def.columns.iter().any(|c| c.name.eq_ignore_ascii_case(n));
        let mut adds = Vec::new();
        for e in from.iter().filter(|e| has(&e.column)) {
            let defs = column_defs(&Clause {
                column: e.column.clone(),
                dim: e.model.dimensions,
                source: e.source.clone(),
                model: e.alias.clone(),
                mode: sprig_sql::embedcol::Mode::Async,
                max_input_tokens: e.max_input_tokens,
                span: 0..0,
            });
            for (name, d) in [
                (embedcol::src_column(&e.column, None), &defs[1]),
                (embedcol::hash_column(&e.column, None), &defs[2]),
            ] {
                if !has(&name) {
                    adds.push(format!("ADD COLUMN {d}"));
                }
            }
        }
        let def = if adds.is_empty() {
            def
        } else {
            let alter = format!(
                "ALTER TABLE {}.{} {}",
                quote(&db),
                quote(&like.table),
                adds.join(", ")
            );
            if let Err(e) = self.embed_run(cx, wire, &alter).await {
                let _ = self
                    .embed_run(
                        cx,
                        wire,
                        &format!("DROP TABLE {}.{}", quote(&db), quote(&like.table)),
                    )
                    .await;
                return Err(e);
            }
            let (cat, lctn) = self.embed_cat().await?;
            table_def(&cat, &db, &like.table, lctn).ok_or_else(|| {
                SprigError::internal(format!("{db}.{} isn't in the catalog", like.table))
            })?
        };
        let has = |n: &str| def.columns.iter().any(|c| c.name.eq_ignore_ascii_case(n));
        let rows: Vec<EngineColumn> = from
            .iter()
            .filter(|e| has(&e.column) && has(&embedcol::hash_column(&e.column, None)))
            .map(|e| EngineColumn {
                id: 0,
                db_id: def.db.0,
                object_id: def.object.0,
                state: State::Backfilling,
                from_ms: now_ms(),
                token: None,
                backfilled: false,
                backfill_after: None,
                rows_embedded: 0,
                rows_failed: 0,
                last_error: None,
                created_by: user,
                ..e.clone()
            })
            .collect();
        if let Err(e) = self.insert_columns(&rows).await {
            let _ = self
                .embed_run(
                    cx,
                    wire,
                    &format!("DROP TABLE {}.{}", quote(&db), quote(&like.table)),
                )
                .await;
            return Err(e);
        }
        super::runner::wake();
        Ok(true)
    }
}

/// 39997 for a new generation on an engine table.
pub(crate) fn modify_refused(column: &str) -> SprigError {
    failed(format!(
        "embedded column {column}: changing the model or source of an embedded column of an engine table isn't available yet; drop the column and add it again"
    ))
}

#[cfg(test)]
mod tests {
    use super::*;
    use sprig_sql::embedcol::Mode;

    #[test]
    fn the_engine_layout_holds_the_vector_as_binary() {
        let c = Clause {
            column: "emb".into(),
            dim: 384,
            source: "CONCAT(title, ' ', body)".into(),
            model: "local:bge-small".into(),
            mode: Mode::Async,
            max_input_tokens: Some(128),
            span: 0..0,
        };
        let d = column_defs(&c);
        assert_eq!(d[0], "`emb` VARBINARY(1536) NULL DEFAULT NULL");
        assert!(
            d[1].starts_with(
                "`_sprig_emb_emb_src` MEDIUMTEXT GENERATED ALWAYS AS (CONCAT(title, ' ', body)) VIRTUAL INVISIBLE COMMENT 'sprig:embedding {"
            ),
            "{}",
            d[1]
        );
        assert!(d[1].contains("\"max_input_tokens\":128"), "{}", d[1]);
        assert_eq!(
            d[2],
            "`_sprig_emb_emb_hash` BINARY(16) NULL DEFAULT NULL INVISIBLE"
        );
        assert_eq!(lit("it's"), "'it''s'");
    }

    #[test]
    fn create_table_like_is_read() {
        let l = parse_like("CREATE TABLE IF NOT EXISTS d2.`b c` LIKE `a`;").unwrap();
        assert_eq!(
            l,
            LikeStmt {
                temporary: false,
                db: Some("d2".into()),
                table: "b c".into(),
                src_db: None,
                src: "a".into(),
            }
        );
        let l = parse_like("create temporary table t (like s.a)").unwrap();
        assert!(l.temporary);
        assert_eq!((l.src_db.as_deref(), l.src.as_str()), (Some("s"), "a"));
        for no in [
            "CREATE TABLE t (id INT)",
            "CREATE TABLE t LIKE a, b",
            "CREATE TABLE t LIKE",
            "/* x */ CREATE TABLE t LIKE a",
            "CREATE TABLE t AS SELECT * FROM a",
        ] {
            assert!(parse_like(no).is_none(), "{no}");
        }
    }
}
